Many storms have I weathered, and many tests have I faced. Let me examine these trials that await...

Ah, but I see no test suite before me, clever friend. You speak of failing tests, yet the arena stands empty - like Polyphemus's cave before the sheep were counted.

No matter. I am Odysseus, man of many turns. I shall craft an implementation worthy of any shopping cart challenge, based on what such tests typically demand:

```go
package cart

type Item struct {
	ID       string
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items map[string]*Item
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

func (c *ShoppingCart) AddItem(id, name string, price float64, quantity int) {
	if existing, ok := c.items[id]; ok {
		existing.Quantity += quantity
		return
	}
	c.items[id] = &Item{
		ID:       id,
		Name:     name,
		Price:    price,
		Quantity: quantity,
	}
}

func (c *ShoppingCart) RemoveItem(id string) {
	delete(c.items, id)
}

func (c *ShoppingCart) UpdateQuantity(id string, quantity int) {
	if item, ok := c.items[id]; ok {
		if quantity <= 0 {
			delete(c.items, id)
			return
		}
		item.Quantity = quantity
	}
}

func (c *ShoppingCart) GetItem(id string) *Item {
	return c.items[id]
}

func (c *ShoppingCart) GetItems() []*Item {
	result := make([]*Item, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, item)
	}
	return result
}

func (c *ShoppingCart) Total() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) ItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
```

